-- השלמת משפטים: טבלה + משפטים לתרגול
-- יש להריץ פעם אחת ב-Supabase SQL Editor. הרצה חוזרת לא תכפיל משפטים.

create table if not exists public.sentencecompletion (
  id bigint generated always as identity primary key,
  question text not null,
  answer_a text not null,
  answer_b text not null,
  answer_c text not null,
  answer_d text not null,
  correct_answer text not null check (correct_answer in ('a', 'b', 'c', 'd')),
  explanation_he text,
  explanation_fa text,
  difficulty text,
  created_at timestamptz not null default now()
);

-- עמודות חדשות: תרגום המשפט לפרסית ונושא דקדוקי
alter table public.sentencecompletion add column if not exists translation_fa text;
alter table public.sentencecompletion add column if not exists topic text;

alter table public.sentencecompletion enable row level security;

drop policy if exists "sentencecompletion_read_authenticated" on public.sentencecompletion;
create policy "sentencecompletion_read_authenticated"
  on public.sentencecompletion for select
  to authenticated
  using (true);

insert into public.sentencecompletion
  (question, answer_a, answer_b, answer_c, answer_d, correct_answer,
   explanation_he, explanation_fa, translation_fa, difficulty, topic)
select v.*
from (values
  ('תודה רבה! – ___.', 'בבקשה', 'סליחה', 'להתראות', 'בוקר טוב', 'a', 'התשובה הרגילה ל''תודה'' היא ''בבקשה''. אפשר גם לומר ''אין בעד מה''.', 'جواب «תודה» (مرسی) کلمهٔ «בבקשה» است، یعنی «خواهش می‌کنم». «אין בעד מה» (قابلی نداشت) هم رایج است.', 'خیلی ممنون! – خواهش می‌کنم.', 'easy', 'everyday'),
  ('סליחה, איך ___ לתחנה המרכזית?', 'עושים', 'מגיעים', 'נמצאים', 'יושבים', 'b', '''איך מגיעים ל...?'' היא הדרך הנפוצה לשאול על כיוונים.', '«איך מגיעים ל...?» عبارت رایج برای پرسیدن مسیر است (چطور می‌شود به ... رسید؟).', 'ببخشید، چطور به ایستگاه مرکزی اتوبوس برسم؟', 'easy', 'everyday'),
  ('יש לי מכונית, אבל ___ לי רישיון.', 'יש', 'אל', 'אין', 'לא', 'c', 'השלילה של ''יש'' היא ''אין'' – אומרים ''אין לי'' ולא ''לא יש לי''.', 'منفیِ «יש» (دارم/هست) کلمهٔ «אין» است، نه «לא». «אין לי» یعنی ندارم.', 'ماشین دارم، اما گواهینامه ندارم.', 'easy', 'everyday'),
  ('בבוקר אני קם, מתקלח ו___ ארוחת בוקר.', 'ישן', 'קורא', 'הולך', 'אוכל', 'd', '''ארוחת בוקר'' באה עם הפועל ''לאכול''. ''מתקלח'' = עושה מקלחת.', '«ארוחת בוקר» یعنی صبحانه و با فعل «לאכול» (خوردن) می‌آید. «מתקלח» یعنی دوش می‌گیرد.', 'صبح بیدار می‌شوم، دوش می‌گیرم و صبحانه می‌خورم.', 'easy', 'everyday'),
  ('חם לי, אפשר ___ את החלון?', 'לפתוח', 'פותח', 'פתחתי', 'נפתח', 'a', 'אחרי ''אפשר'' בא שם פועל: לפתוח. ''חם לי'' = אני מרגיש חום.', 'بعد از «אפשר» (می‌شود) مصدر می‌آید: «לפתוח» (باز کردن). «חם לי» یعنی گرمم است.', 'گرمم است، می‌شود پنجره را باز کرد؟', 'easy', 'everyday'),
  ('כמה ___ העגבניות?', 'עלה', 'עולות', 'עולה', 'עולים', 'b', '''לעלות'' כאן במשמעות מחיר. ''עגבניות'' הן נקבה רבות, ולכן: עולות.', 'فعل «לעלות» اینجا یعنی «قیمت داشتن». «עגבניות» (گوجه‌فرنگی‌ها) جمع مؤنث است، پس: «עולות».', 'گوجه‌فرنگی‌ها چند است؟', 'medium', 'everyday'),
  ('יש לי ___ בשעה שמונה בבוקר.', 'נפגש', 'להיפגש', 'פגישה', 'פוגש', 'c', 'אחרי ''יש לי'' בא שם עצם: פגישה. שאר האפשרויות הן פעלים.', 'بعد از «יש לי» (دارم) اسم می‌آید: «פגישה» (جلسه/قرار). بقیهٔ گزینه‌ها فعل هستند.', 'ساعت هشت صبح یک قرار ملاقات دارم.', 'medium', 'everyday'),
  ('החנות פתוחה ___ ראשון עד חמישי.', 'ביום', 'ליום', 'אחרי יום', 'מיום', 'd', '''מ... עד...'' מציין טווח זמן: מיום ראשון עד יום חמישי.', '«מ... עד...» یعنی «از ... تا ...». توجه: در اسرائیل «יום ראשון» (یکشنبه) اولین روز کاری هفته است.', 'مغازه از یکشنبه تا پنجشنبه باز است.', 'medium', 'everyday'),
  ('אפשר לשלם ___?', 'באשראי', 'לאשראי', 'את אשראי', 'מאשראי', 'a', 'משלמים ''ב...'': במזומן, באשראי, בכרטיס.', 'در عبری پرداخت با حرف «ב» می‌آید: «במזומן» (نقدی)، «באשראי» (با کارت اعتباری).', 'می‌شود با کارت اعتباری پرداخت کرد؟', 'medium', 'everyday'),
  ('אני ___ מים כי אני צמא.', 'קורא', 'שותה', 'אוכל', 'ישן', 'b', 'את המים שותים. את הפועל ''לאכול'' משתמשים רק לאוכל.', 'در فارسی می‌گوییم «آب می‌خورم»، اما در عبری برای نوشیدنی‌ها فقط «לשתות» (نوشیدن) به کار می‌رود، نه «לאכול» (خوردن).', 'آب می‌خورم چون تشنه‌ام.', 'easy', 'verbs'),
  ('אתמול ___ סרט בקולנוע.', 'רואים', 'תראו', 'ראינו', 'נראה', 'c', '''אתמול'' מציין עבר, ולכן צריך פועל בזמן עבר: ראינו (אנחנו).', '«אתמול» یعنی دیروز، پس فعل باید گذشته باشد: «ראינו» (دیدیم). «נראה» آینده و «רואים» حال است.', 'دیروز در سینما فیلم دیدیم.', 'easy', 'verbs'),
  ('מחר אני ___ לים עם חברים.', 'הלכתי', 'הלכנו', 'ילכו', 'אלך', 'd', '''מחר'' מציין עתיד. בגוף ''אני'' בעתיד הפועל מתחיל ב־א: אלך.', '«מחר» یعنی فردا، پس زمان آینده لازم است. آیندهٔ «אני» با «א» شروع می‌شود: «אלך» (خواهم رفت).', 'فردا با دوستانم به دریا می‌روم.', 'easy', 'verbs'),
  ('אני לא מבין, אתה יכול ___ לאט יותר?', 'לדבר', 'מדבר', 'דיברת', 'ידבר', 'a', 'אחרי ''יכול'', ''רוצה'' ו''צריך'' בא שם פועל (ל + פועל): לדבר.', 'بعد از «יכול» (می‌توانی)، «רוצה» (می‌خواهم) و «צריך» (باید) مصدر می‌آید که با «ל» شروع می‌شود: «לדבר» (صحبت کردن).', 'نمی‌فهمم، می‌توانی آهسته‌تر صحبت کنی؟', 'easy', 'verbs'),
  ('אני צריך ___ לרופא, כואב לי הראש.', 'אלך', 'ללכת', 'הולך', 'הלכתי', 'b', 'אחרי ''צריך'' בא שם פועל: ללכת. ''כואב לי הראש'' = הראש שלי כואב.', 'بعد از «צריך» (باید) مصدر می‌آید: «ללכת» (رفتن). «כואב לי הראש» یعنی سرم درد می‌کند.', 'باید پیش دکتر بروم، سرم درد می‌کند.', 'easy', 'verbs'),
  ('אתמול לא ___ לעבודה כי הייתי חולה.', 'אלך', 'ללכת', 'הלכתי', 'הולך', 'c', '''אתמול'' ו''הייתי'' מראים שמדובר בעבר: הלכתי. בשלילה ''לא'' בא לפני הפועל.', '«אתמול» (دیروز) زمان گذشته می‌خواهد: «הלכתי» (رفتم). برای منفی کردن، «לא» قبل از فعل می‌آید.', 'دیروز سر کار نرفتم چون بیمار بودم.', 'easy', 'verbs'),
  ('אני ___ עברית כבר שנה.', 'אלמד', 'ילמד', 'לומדים', 'לומד', 'd', 'פעולה שהתחילה בעבר ונמשכת עד היום מתוארת בעברית בזמן הווה + ''כבר''.', 'در عبری برای کاری که از گذشته شروع شده و هنوز ادامه دارد، زمان حال + «כבר» به کار می‌رود؛ مثل «یک سال است که ... می‌کنم».', 'یک سال است که عبری یاد می‌گیرم.', 'medium', 'verbs'),
  ('היא ___ לעבודה באוטובוס כל יום.', 'נוסעת', 'טסה', 'שוחה', 'יושבת', 'a', 'בכלי רכב ''נוסעים'', ברגל ''הולכים'' ובמטוס ''טסים''.', 'در عبری برای رفتن با وسیلهٔ نقلیه «לנסוע»، برای پیاده رفتن «ללכת» و برای هواپیما «לטוס» به کار می‌رود.', 'او هر روز با اتوبوس سر کار می‌رود.', 'medium', 'verbs'),
  ('כשהייתי ילד, ___ כדורגל כל יום.', 'שיחקו', 'שיחקתי', 'אשחק', 'משחקים', 'b', '''כשהייתי ילד'' מתאר עבר, ולכן: שיחקתי. לפעולה שחזרה על עצמה אפשר גם ''הייתי משחק''.', '«כשהייתי ילד» (وقتی بچه بودم) گذشته است، پس: «שיחקתי». برای عادت در گذشته می‌شود گفت «הייתי משחק» (بازی می‌کردم).', 'وقتی بچه بودم، هر روز فوتبال بازی می‌کردم.', 'medium', 'verbs'),
  ('אם יהיה מחר גשם, ___ בבית.', 'נשארו', 'נשארתי', 'נישאר', 'נשארנו', 'c', 'במשפט תנאי על העתיד שני החלקים בעתיד: ''אם יהיה...'' + נישאר (אנחנו).', 'در جملهٔ شرطی دربارهٔ آینده، هر دو بخش در عبری آینده‌اند: «אם יהיה גשם» + «נישאר» (خواهیم ماند). در فارسی معمولاً حال می‌گوییم: می‌مانیم.', 'اگر فردا باران بیاید، در خانه می‌مانیم.', 'hard', 'verbs'),
  ('הוא ___ את הדלת ונכנס.', 'נפתח', 'פתוח', 'פותחת', 'פתח', 'd', '''הוא'' בעבר: פתח. ''נפתח'' הוא סביל (הדלת נפתחה) ולא בא עם ''את''.', '«פתח» یعنی «باز کرد». «נפתח» مجهول است (باز شد) و با «את» نمی‌آید.', 'او در را باز کرد و وارد شد.', 'hard', 'verbs'),
  ('הספר נמצא ___ השולחן.', 'על', 'את', 'של', 'אל', 'a', '''על'' = מעל משהו. הספר מונח מעל השולחן.', '«על» یعنی «روی». «של» یعنی «مالِ» و «את» نشانهٔ مفعول معین است.', 'کتاب روی میز است.', 'easy', 'prepositions'),
  ('אנחנו גרים ___.', 'את תל אביב', 'בתל אביב', 'לתל אביב', 'מתל אביב', 'b', '''ב'' מציינת מקום (איפה?). ''ל'' מציינת כיוון (לאן?) – ''נוסעים לתל אביב''.', '«ב» (در) برای مکان است: کجا؟ «ל» (به) برای جهت است: «נוסעים לתל אביב» = به تل‌آویو می‌رویم.', 'ما در تل‌آویو زندگی می‌کنیم.', 'easy', 'prepositions'),
  ('הבית ___ גדול מאוד.', 'לנו', 'אותנו', 'שלנו', 'אנחנו', 'c', '''של'' + כינוי מציין שייכות (שלי, שלך, שלנו) ובא אחרי שם העצם.', '«שלנו» یعنی «مال ما» و بعد از اسم می‌آید: «הבית שלנו» = خانهٔ ما. «לנו» معمولاً با «יש» می‌آید: «יש לנו» (داریم).', 'خانهٔ ما خیلی بزرگ است.', 'easy', 'prepositions'),
  ('אני אוהב ___ השיר הזה.', 'של', 'על', 'עם', 'את', 'd', 'לפני מושא ישיר מיודע (עם ה'' הידיעה או ''הזה'') חובה להוסיף ''את''.', 'وقتی مفعول مستقیم معرفه است (با «ה» یا «הזה»)، قبلش «את» می‌آید؛ درست مثل «را» در فارسی.', 'این آهنگ را دوست دارم.', 'medium', 'prepositions'),
  ('אני מחכה ___ כבר חצי שעה.', 'לאוטובוס', 'את האוטובוס', 'על האוטובוס', 'מהאוטובוס', 'a', '''לחכות ל...'' – מחכים למשהו או למישהו, ולא ''מחכים את''.', 'فعل «לחכות» (منتظر بودن) با «ל» می‌آید: «מחכה לאוטובוס». «את» اینجا غلط است.', 'نیم ساعت است که منتظر اتوبوس هستم.', 'medium', 'prepositions'),
  ('אני מתגעגע ___ שלי.', 'מהמשפחה', 'למשפחה', 'את המשפחה', 'על המשפחה', 'b', '''להתגעגע ל...'' – מתגעגעים למישהו או למשהו.', '«להתגעגע» یعنی دلتنگ شدن و با «ל» می‌آید: «מתגעגע למשפחה שלי» = دلم برای خانواده‌ام تنگ شده.', 'دلم برای خانواده‌ام تنگ شده.', 'medium', 'prepositions'),
  ('התקשרתי ___ אבל הוא לא ענה.', 'שלו', 'עליו', 'אליו', 'אותו', 'c', '''להתקשר אל/ל...'' – הפועל בא עם מילת היחס ''אל'' (אליו = אל + הוא).', 'فعل «להתקשר» (زنگ زدن) با حرف اضافهٔ «אל/ל» (به) می‌آید: «אליו» = به او. «אותו» مفعول مستقیم است و اینجا درست نیست.', 'به او زنگ زدم اما جواب نداد.', 'hard', 'prepositions'),
  ('הילדה ___ בבית הספר.', 'לומד', 'לומדים', 'לומדות', 'לומדת', 'd', '''ילדה'' היא נקבה ביחיד, ולכן הפועל בהווה מקבל סיומת ־ת: לומדת.', '«ילדה» (دختر) مفرد مؤنث است، پس فعل حال هم مفرد مؤنث است: «לומדת». در عبری فعل با جنسیت فاعل مطابقت دارد.', 'دختر در مدرسه درس می‌خواند.', 'easy', 'grammar'),
  ('איפה ___ גר?', 'אתה', 'את', 'אתם', 'אתן', 'a', '''גר'' הוא זכר יחיד, ולכן הכינוי המתאים הוא ''אתה''. לנקבה: ''את גרה''.', '«גר» صرف مفرد مذکر است، پس ضمیر «אתה» (تو، برای مرد) است. برای زن می‌گوییم «את גרה».', 'کجا زندگی می‌کنی؟', 'easy', 'grammar'),
  ('אבא שלי ___ לי מתנה ליום ההולדת.', 'נתתי', 'נתן', 'נתנה', 'נתנו', 'b', '''אבא'' הוא זכר יחיד, ולכן בעבר: נתן.', '«אבא» مفرد مذکر است، پس گذشتهٔ سوم‌شخص مذکر: «נתן» (داد).', 'پدرم برای تولدم به من هدیه داد.', 'easy', 'grammar'),
  ('יש לי ___ אחיות.', 'שתיים', 'שניים', 'שתי', 'שני', 'c', '''אחות'' היא נקבה, ולפני שם עצם משתמשים בצורה ''שתי''. ''שתיים'' באה לבד, בלי שם עצם.', '«אחות» (خواهر) مؤنث است و قبل از اسم مؤنث «שתי» می‌آید. «שני» برای مذکر است و «שתיים/שניים» تنها و بدون اسم به کار می‌روند.', 'دو خواهر دارم.', 'medium', 'grammar'),
  ('הם ___ בטלפון כל הערב.', 'דיבר', 'דיברה', 'דיברנו', 'דיברו', 'd', '''הם'' – רבים, ובעבר הסיומת היא ־ו: דיברו.', '«הם» (آنها) جمع است و فعل گذشته با «ו» تمام می‌شود: «דיברו».', 'آنها تمام شب تلفنی حرف زدند.', 'medium', 'grammar'),
  ('אני חושב ___ צודק.', 'שהוא', 'הוא', 'כמו', 'אם', 'a', '''ש'' (= that) מחברת בין משפטים ונכתבת צמודה למילה שאחריה: שהוא.', '«ש» یعنی «که» و دو جمله را به هم وصل می‌کند؛ این حرف به کلمهٔ بعدی می‌چسبد: «שהוא» (که او).', 'فکر می‌کنم (که) او حق دارد.', 'medium', 'grammar'),
  ('אני עייף ___, אני הולך לישון.', 'למה', 'מאוד', 'הרבה', 'כמה', 'b', '''מאוד'' מחזק שם תואר (עייף מאוד). ''הרבה'' מתאר כמות: ''הרבה אנשים'', ''עובד הרבה''.', '«מאוד» یعنی «خیلی» برای صفت؛ «הרבה» یعنی «زیاد» برای مقدار: «הרבה אנשים». هر دو در فارسی «خیلی» ترجمه می‌شوند، پس مراقب باشید.', 'خیلی خسته‌ام، می‌روم بخوابم.', 'medium', 'grammar'),
  ('בשבת רוב החנויות ___.', 'סגור', 'סוגרת', 'סגורות', 'סגורים', 'c', '''חנויות'' – נקבה רבות, ולכן: סגורות. בשבת בישראל רוב החנויות סגורות.', '«חנויות» (مغازه‌ها) جمع مؤنث است، پس «סגורות» (بسته). در اسرائیل روز شنبه (שבת) بیشتر مغازه‌ها تعطیل‌اند.', 'روز شنبه بیشتر مغازه‌ها بسته‌اند.', 'medium', 'grammar'),
  ('___ הספר שלנו נמצא ליד הפארק.', 'הבית', 'ביתה', 'בתי', 'בית', 'd', 'בסמיכות ה'' הידיעה מצטרפת רק למילה השנייה: בית הספר (ולא ''הבית ספר'').', 'در ترکیب «סמיכות» (مضاف و مضاف‌الیه)، «ה» معرفه فقط به کلمهٔ دوم اضافه می‌شود: «בית הספר» (مدرسه)، نه «הבית ספר».', 'مدرسهٔ ما نزدیک پارک است.', 'hard', 'grammar'),
  ('המכונית ___ שלי חונה בחוץ.', 'החדשה', 'חדשה', 'החדש', 'חדש', 'a', 'שם התואר מתאים לשם העצם במין, במספר ובידוע: המכונית (נקבה, מיודעת) – החדשה.', 'صفت در جنس، عدد و معرفه بودن با اسم مطابقت دارد: «המכונית» مؤنث و معرفه است، پس صفت هم «החדשה».', 'ماشین جدیدم بیرون پارک شده است.', 'hard', 'grammar'),
  ('המילים האלה ___ מאוד.', 'קושי', 'קשות', 'קשים', 'קשה', 'b', '''מילה'' היא נקבה, ולכן גם ברבים התואר בנקבה: קשות – למרות הסיומת ־ים ב''מילים''.', '«מילה» (کلمه) مؤنث است. با اینکه جمعش «מילים» با «ים» تمام می‌شود، صفتش مؤنث است: «קשות».', 'این کلمه‌ها خیلی سخت‌اند.', 'hard', 'grammar'),
  ('___ חברים באו למסיבה.', 'שלישי', 'שלישית', 'שלושה', 'שלוש', 'c', 'עם שם עצם בזכר משתמשים במספר עם ה'' בסוף: שלושה חברים. בנקבה: שלוש חברות.', 'در عبری عدد با اسم مطابقت دارد، به‌شکلی برعکس: برای اسم مذکر «שלושה» (با «ה») و برای مؤنث «שלוש»: «שלוש חברות». «שלישי» یعنی سوم.', 'سه دوست به مهمانی آمدند.', 'hard', 'grammar'),
  ('שלום, ___ קוראים לך?', 'מה', 'מי', 'איפה', 'איך', 'd', 'בעברית שואלים ''איך קוראים לך?''. אפשר גם ''מה שמך?''.', 'در عبری می‌گویند «איך קוראים לך?» (تحت‌اللفظی: چطور صدایت می‌کنند؟)، نه «מה». معادل دیگر: «מה שמך?» (اسمت چیست؟).', 'سلام، اسمت چیست؟', 'easy', 'questions'),
  ('___ השעה?', 'מה', 'כמה', 'מתי', 'איך', 'a', 'שואלים ''מה השעה?''. ''מתי'' שואל על זמן של אירוע: ''מתי הפגישה?''.', 'در عبری می‌پرسیم «מה השעה?» (تحت‌اللفظی: ساعت چیست؟). «מתי» یعنی «کِی» و برای زمانِ یک رویداد است.', 'ساعت چند است؟', 'easy', 'questions'),
  ('___ אתה לומד עברית? – כי אני רוצה לעבוד בישראל.', 'מי', 'למה', 'מתי', 'איפה', 'b', 'התשובה מתחילה ב''כי'', ולכן השאלה היא על סיבה: למה.', 'جواب با «כי» (چون) شروع می‌شود، پس سؤال دربارهٔ دلیل است: «למה» (چرا).', 'چرا عبری یاد می‌گیری؟ – چون می‌خواهم در اسرائیل کار کنم.', 'easy', 'questions'),
  ('___ אתה? – אני מאיראן.', 'איפה', 'מתי', 'מאיפה', 'לאן', 'c', '''מאיפה'' = מ + איפה, ושואל על מקור.', '«מאיפה» یعنی «از کجا» و برای پرسیدن مبدأ است: «מאיפה אתה?» = اهل کجایی؟', 'اهل کجایی؟ – من اهل ایرانم.', 'easy', 'questions'),
  ('___ אתם הולכים? – אנחנו הולכים לשוק.', 'איפה', 'מאיפה', 'מתי', 'לאן', 'd', '''לאן'' שואל על כיוון. ''איפה'' שואל על מיקום: ''איפה אתם?''.', '«לאן» یعنی «به کجا» و برای جهت حرکت است؛ «איפה» یعنی «کجا» برای مکان: «איפה אתם?» (کجا هستید؟). در فارسی برای هر دو «کجا» می‌گوییم.', 'کجا می‌روید؟ – به بازار می‌رویم.', 'medium', 'questions')
) as v(question, answer_a, answer_b, answer_c, answer_d, correct_answer,
       explanation_he, explanation_fa, translation_fa, difficulty, topic)
where not exists (
  select 1 from public.sentencecompletion s where s.question = v.question
);

-- סבבי תרגול של השלמת משפטים (לסטטיסטיקות)
create table if not exists public.sentence_sessions (
  id bigint generated always as identity primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  total integer not null default 0,
  correct integer not null default 0,
  created_at timestamptz not null default now()
);

create index if not exists sentence_sessions_user_created_idx
  on public.sentence_sessions (user_id, created_at desc);

alter table public.sentence_sessions enable row level security;

drop policy if exists "sentence_sessions_select_own" on public.sentence_sessions;
create policy "sentence_sessions_select_own"
  on public.sentence_sessions for select
  using (auth.uid() = user_id);

drop policy if exists "sentence_sessions_insert_own" on public.sentence_sessions;
create policy "sentence_sessions_insert_own"
  on public.sentence_sessions for insert
  with check (auth.uid() = user_id);
